from pathlib import Path
from playwright.sync_api import sync_playwright
import json
P=Path(__file__).parent;H=P.parent/'Ally_Quest_Stage155.html'; errors=[];requests=[];passed=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=__import__('os').environ.get('AQ_CHROMIUM','/usr/bin/chromium'),headless=True,args=['--no-sandbox','--disable-dev-shm-usage']);p=b.new_page(viewport={'width':1280,'height':720});p.on('pageerror',lambda e:errors.append(str(e)));p.on('request',lambda r:requests.append(r.url));p.evaluate('''()=>{for(const k of ['localStorage','sessionStorage']){const m=new Map();Object.defineProperty(window,k,{value:{getItem:k=>m.get(k)??null,setItem:(k,v)=>m.set(k,String(v)),removeItem:k=>m.delete(k)}})}}''');p.set_content(H.read_text(),wait_until='load');p.wait_for_timeout(500);assert p.locator('#home-play').is_visible();passed.append('Exact standalone bytes load in a harness with storage stub and QA disabled');assert p.evaluate('typeof ALLY_DEBUG === "undefined" && typeof ALLY_ROOM_QA === "undefined"');passed.append('QA APIs absent in normal production boot');p.locator('#home-play').click();p.wait_for_timeout(400);assert p.locator('#hud').is_visible();p.keyboard.down('ArrowRight');p.wait_for_timeout(350);p.keyboard.up('ArrowRight');assert not errors,errors;passed.append('Normal user boot and keyboard motion have no reported page errors');assert not [v for v in requests if v.startswith(('https:','http:'))],requests;passed.append('No external HTTP requests during normal boot and movement');p.screenshot(path=str(P/'qa'/'production-boot.png'));b.close()
(P/'qa'/'production-results.json').write_text(json.dumps({'passed':passed,'errors':errors},indent=2));print(passed)
